package lk.gov.health.govcare.audit;
import lk.gov.health.govcare.common.*;import lk.gov.health.govcare.security.*;import org.springframework.http.*;import org.springframework.security.access.prepost.PreAuthorize;import org.springframework.web.bind.annotation.*;import java.util.*;
@RestController @RequestMapping("/api/login-activities") public class LoginActivityController{private final SqlSupport sql;private final CurrentUser current;public LoginActivityController(SqlSupport sql,CurrentUser current){this.sql=sql;this.current=current;}
@PostMapping public ResponseEntity<Map<String,Object>> create(@RequestBody Map<String,Object> in){String email=Objects.toString(in.get("email"),"").trim();String session=Objects.toString(in.get("sessionId"),"").trim();if(email.isEmpty()||session.isEmpty())throw ApiException.badRequest("email and sessionId are required.");Map<String,Object>u=sql.one("select u.id::text,u.hospital_id::text,u.role::text,u.full_name,u.email,d.name department_name from app_users u left join departments d on d.id=u.department_id where lower(u.email)=lower(:email) limit 1",Map.of("email",email)).orElse(Map.of());Map<String,Object>p=new HashMap<>();p.put("hospital",u.get("hospital_id"));p.put("user",u.get("id"));p.put("session",session);p.put("name",u.getOrDefault("full_name","Unknown user"));p.put("role",u.get("role"));p.put("department",u.get("department_name"));p.put("email",email.toLowerCase());p.put("login",Objects.toString(in.getOrDefault("loginStatus","failed")));p.put("logout",p.get("login").equals("success")?"active":"unknown");p.put("device",in.get("deviceBrowser"));p.put("os",in.get("operatingSystem"));p.put("location",in.get("location"));p.put("method",Objects.toString(in.getOrDefault("authenticationMethod","password")));p.put("reason",in.get("failureReason"));Map<String,Object>row=sql.required("insert into login_activities(hospital_id,user_id,session_id,full_name,role,department_name,email,login_status,logout_status,device_browser,operating_system,location,authentication_method,failure_reason,last_activity_time) values(cast(:hospital as uuid),cast(:user as uuid),:session,:name,cast(:role as user_role),:department,:email,:login,:logout,:device,:os,:location,:method,:reason,now()) returning id::text",p,"Unable to record login activity.");return ResponseEntity.status(HttpStatus.CREATED).body(row);}
@GetMapping @PreAuthorize("hasAuthority('LOGIN_ACTIVITY_VIEW')")public Map<String,Object> list(){GovCarePrincipal a=current.get();String where=a.role().equals("super_admin")?"":" where la.hospital_id=:hospital";Map<String,Object>p=a.role().equals("super_admin")?Map.of():Map.of("hospital",a.hospitalId());return Map.of("items",sql.list("select la.id::text id,la.session_id \"sessionId\",la.user_id::text \"userId\",la.full_name \"fullName\",la.role::text role,la.hospital_id::text \"hospitalId\",h.name \"hospitalName\",u.department_id::text \"departmentId\",la.department_name \"departmentName\",la.email,la.login_status \"loginStatus\",la.logout_status \"logoutStatus\",la.login_time \"loginTime\",la.logout_time \"logoutTime\",la.session_duration_seconds \"sessionDurationSeconds\",la.ip_address \"ipAddress\",la.device_browser \"deviceBrowser\",la.operating_system \"operatingSystem\",la.location,la.authentication_method \"authenticationMethod\",la.failure_reason \"failureReason\",la.last_activity_time \"lastActivityTime\",la.created_at timestamp,la.created_at \"createdAt\" from login_activities la left join app_users u on u.id=la.user_id left join hospitals h on h.id=la.hospital_id"+where+" order by la.login_time desc limit 1000",p));}
@PostMapping("/session/close")public Map<String,Object> close(@RequestBody Map<String,Object>in){GovCarePrincipal a=current.get();String session=Objects.toString(in.get("sessionId"),"").trim();if(session.isEmpty())throw ApiException.badRequest("sessionId is required.");int n=sql.update("update login_activities set logout_status=:status,logout_time=now(),last_activity_time=now(),session_duration_seconds=greatest(0,extract(epoch from(now()-login_time))::int),device_browser=coalesce(:device,device_browser),operating_system=coalesce(:os,operating_system) where session_id=:session and user_id=:user and logout_time is null",map("status",Objects.toString(in.getOrDefault("logoutStatus","logged_out")),"device",in.get("deviceBrowser"),"os",in.get("operatingSystem"),"session",session,"user",a.id()));if(n==0)throw ApiException.notFound("Active login session was not found.");return Map.of("ok",true);}private static Map<String,Object>map(Object...x){Map<String,Object>m=new HashMap<>();for(int i=0;i<x.length;i+=2)m.put(String.valueOf(x[i]),x[i+1]);return m;}}
